div.script:

document.title = "dormo.io - Reaction Test";

let gameState = 'IDLE'; // IDLE, WAITING, READY, RESULT
let startTime = 0;
let timerInterval = null;
let timeoutId = null;

const box = document.getElementById('gameBox');
const mainText = document.getElementById('mainText');
const subText = document.getElementById('subText');
const bestScoreEl = document.getElementById('bestScore');

// Load saved best score from localStorage on startup
let savedBest = localStorage.getItem('dormo_io_best_time');
let bestTime = savedBest !== null ? parseFloat(savedBest) : null;

if (bestTime !== null) {
  bestScoreEl.textContent = 'Best Time: ' + bestTime.toFixed(3) + ' s';
}

function handleClick() {
  if (gameState === 'IDLE' || gameState === 'RESULT') {
    // Enter waiting phase
    gameState = 'WAITING';
    box.style.background = '#ef4444'; // Red
    mainText.textContent = 'Wait for Green...';
    subText.textContent = '';

    const randomDelay = Math.random() * 2500 + 1500; // 1.5 to 4 seconds
    timeoutId = setTimeout(() => {
      gameState = 'READY';
      box.style.background = '#22c55e'; // Green
      mainText.textContent = 'CLICK NOW!';
      subText.textContent = '0.000 s';
      startTime = performance.now();

      // Start live counter
      timerInterval = setInterval(() => {
        const elapsed = (performance.now() - startTime) / 1000;
        subText.textContent = elapsed.toFixed(3) + ' s';
      }, 10);
    }, randomDelay);

  } else if (gameState === 'WAITING') {
    // Clicked too early!
    clearTimeout(timeoutId);
    gameState = 'IDLE';
    box.style.background = '#eab308'; // Warning Yellow
    mainText.textContent = 'Too Early!';
    subText.textContent = 'Click to try again';

  } else if (gameState === 'READY') {
    // Successful reaction click!
    clearInterval(timerInterval);
    const reactionTime = (performance.now() - startTime) / 1000;
    gameState = 'RESULT';
    box.style.background = '#3b82f6'; // Blue result card
    mainText.textContent = reactionTime.toFixed(3) + ' s';
    subText.textContent = 'Click to play again';

    if (bestTime === null || reactionTime < bestTime) {
      bestTime = reactionTime;
      localStorage.setItem('dormo_io_best_time', bestTime);
      bestScoreEl.textContent = 'Best Time: ' + bestTime.toFixed(3) + ' s';
    }
  }
}
